+        expect(container.querySelector("bdi > a")).not.toBeInTheDocument();
+    });
+
+    it("uses a span outside messages and shows @room with the current room avatar", () => {
+        const { container } = render(<Pill type={PillType.AtRoomMention} room={room} inMessage shouldShowPillAvatar />);
